fs.mkdirSync(outDir, { recursive: true });

function download(url) {
  return new Promise(function (resolve, reject) {
    var client = url.indexOf('https:') === 0 ? https : http;
    client.get(url, { headers: { 'User-Agent': 'Mozilla/5.0' } }, function (res) {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        var next = res.headers.location;
        if (next.indexOf('http') !== 0) {
          next = 'https://tamduchearthospital.com' + (next.charAt(0) === '/' ? '' : '/') + next;
        }
        res.resume();
        return resolve(download(next));
      }
      if (res.statusCode !== 200) {
        res.resume();
        return reject(new Error('HTTP ' + res.statusCode + ' for ' + url));
      }
      var chunks = [];
      res.on('data', function (chunk) { chunks.push(chunk); });
      res.on('end', function () { resolve(Buffer.concat(chunks)); });
    }).on('error', reject);
  });
}

function getSharp() {
  try {
    return require(sharpPath);
  } catch (e1) {
    try {
      return require('sharp');
    } catch (e2) {
      return null;
    }
  }
}

function saveBuffer(name, buffer, asWebp) {
  var sharp = getSharp();
  if (asWebp && sharp) {
    return sharp(buffer).webp({ quality: 85 }).toBuffer().then(function (webpBuffer) {
      fs.writeFileSync(path.join(outDir, name), webpBuffer);
      return webpBuffer.length;
    });
  }
  fs.writeFileSync(path.join(outDir, name), buffer);
  return Promise.resolve(buffer.length);
}

function extractBase64Images(html) {
  var regex = /href="(data:image\/(?:png|jpeg|jpg|webp);base64,[^"]+)"/g;
  var results = [];
  var match;
  while ((match = regex.exec(html)) !== null) {
    results.push(match[1]);
  }
  return results;
}

function decodeDataUrl(dataUrl) {
  var comma = dataUrl.indexOf(',');
  var meta = dataUrl.substring(0, comma);
  var data = dataUrl.substring(comma + 1);
  var buffer = Buffer.from(data, 'base64');
  var ext = '.png';
  if (meta.indexOf('jpeg') >= 0 || meta.indexOf('jpg') >= 0) ext = '.jpg';
  if (meta.indexOf('webp') >= 0) ext = '.webp';
  return { buffer: buffer, ext: ext };
}

function copyPlaceholder() {
  var src = path.join(root, 'HOS', 'Media', 'About', 'leader-placeholder.svg');
  var dest = path.join(outDir, 'leader-placeholder.svg');
  if (fs.existsSync(src) && !fs.existsSync(dest)) {
    fs.copyFileSync(src, dest);
  }
}

(async function () {
  var ok = 0;
  var fail = 0;

  copyPlaceholder();

  for (var i = 0; i < urlFiles.length; i++) {
    var entry = urlFiles[i];
    var name = entry[0];
    var url = entry[1];
    var asWebp = entry[2] === 'webp' || name.indexOf('.webp') >= 0;
    try {
      var buffer = await download(url);
      var size = await saveBuffer(name, buffer, asWebp);
      console.log('OK  ' + name + ' (' + size + ' bytes) <- ' + url);
      ok++;
    } catch (err) {
      console.log('FAIL ' + name + ' -> ' + err.message);
      fail++;
    }
  }

  if (fs.existsSync(htmlPath)) {
    var html = fs.readFileSync(htmlPath, 'utf8');
    var base64Images = extractBase64Images(html);
    console.log('Found ' + base64Images.length + ' embedded base64 images in HTML');

    for (var j = 0; j < base64Images.length && j < boardProfileNames.length; j++) {
      try {
        var decoded = decodeDataUrl(base64Images[j]);
        var boardName = boardProfileNames[j];
        var boardPath = path.join(outDir, boardName);
        fs.writeFileSync(boardPath, decoded.buffer);
        console.log('OK  ' + boardName + ' (' + decoded.buffer.length + ' bytes) <- base64 in HTML');
        ok++;
      } catch (err2) {
        console.log('FAIL ' + boardProfileNames[j] + ' -> ' + err2.message);
        fail++;
      }
    }
  } else {
    console.log('WARN HTML not found: ' + htmlPath);
  }

  console.log('Done. OK=' + ok + ' FAIL=' + fail);
  console.log('Output: ' + outDir);
})();

