using System;
using System.Data;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using System.Web;
using System.Web.UI;
using InformationWeb;
using InformationWebObject;

namespace InformationWeb.Controls.Information.BanLanhDao
{
    /// <summary>
    /// Trang Ban Lanh Dao - noi dung hien thi tu CMS (GetPublished).
    /// Markup mau chi dung khi cmsTemplate=1 de CMS import; khong phai noi dung live.
    /// </summary>
    public partial class SectionBanLanhDao : System.Web.UI.UserControl
    {
        protected bool HasFullPage { get; private set; }
        protected string FullPageHtml { get; private set; }
        protected string FullPageCss { get; private set; }
        protected bool IsCmsTemplateMode { get; private set; }

        protected void Page_Load(object sender, EventArgs e)
        {
            IsCmsTemplateMode = string.Equals(Request["cmsTemplate"], "1", StringComparison.OrdinalIgnoreCase);

            if (IsCmsTemplateMode)
            {
                Response.AppendHeader("Access-Control-Allow-Origin", "*");
                Response.AppendHeader("Access-Control-Allow-Methods", "GET, OPTIONS");
                Response.AppendHeader("Access-Control-Allow-Headers", "Content-Type");
                Response.Cache.SetCacheability(HttpCacheability.NoCache);
            }

            LoadPageContent();
        }

        private void LoadPageContent()
        {
            HasFullPage = false;
            FullPageHtml = string.Empty;
            FullPageCss = string.Empty;

            int languageId = GetRequestedLanguageId();
            if (TryLoadFullPage(languageId))
                return;

            if (IsCmsTemplateMode)
                TryLoadTemplateFallback();
        }

        private int GetRequestedLanguageId()
        {
            int languageId = ResManager.CurrentLanguageID;
            if (IsCmsTemplateMode)
            {
                int requestedLanguageId;
                if (int.TryParse(Request["languageId"], out requestedLanguageId)
                    && (requestedLanguageId == 1 || requestedLanguageId == 2))
                {
                    languageId = requestedLanguageId;
                }
            }
            return languageId;
        }

        private bool TryLoadFullPage(int languageId)
        {
            try
            {
                INFO_Information objInformation = new INFO_Information();
                DataTable data = objInformation.GetDataTable(
                    "CMS_BanLanhDaoPage_GetPublished",
                    "@LanguageID", languageId
                );

                if (data == null || data.Rows.Count < 1)
                    return false;

                DataRow row = data.Rows[0];
                string html = GetRowValue(row, "HtmlBody");
                if (string.IsNullOrWhiteSpace(html))
                    return false;

                html = SanitizeHtml(html);
                html = NormalizeBanLanhDaoShell(html);
                html = EnsureBanLanhDaoRootAttribute(html);
                if (html.IndexOf("ban-lanh-dao-page", StringComparison.OrdinalIgnoreCase) < 0)
                {
                    html = "<div class=\"ban-lanh-dao-page\" data-ban-lanh-dao-root=\"1\"><div class=\"ban-lanh-dao-page-body\">"
                        + html + "</div></div>";
                }

                FullPageHtml = html;
                FullPageCss = SanitizeCss(GetRowValue(row, "CssText"));
                HasFullPage = true;
                return true;
            }
            catch
            {
                HasFullPage = false;
                FullPageHtml = string.Empty;
                FullPageCss = string.Empty;
                return false;
            }
        }

        private bool TryLoadTemplateFallback()
        {
            try
            {
                string path = Server.MapPath("~/Controls/Information/BanLanhDao/SectionBanLanhDao.template.inc");
                if (!File.Exists(path))
                    return false;

                string html = File.ReadAllText(path, Encoding.UTF8);
                if (html.Length > 0 && html[0] == '\uFEFF')
                    html = html.Substring(1);

                html = SanitizeHtml(html.Trim());
                html = NormalizeBanLanhDaoShell(html);
                html = EnsureBanLanhDaoRootAttribute(html);
                if (string.IsNullOrWhiteSpace(html))
                    return false;

                FullPageHtml = html;
                FullPageCss = string.Empty;
                HasFullPage = true;
                return true;
            }
            catch
            {
                return false;
            }
        }

        private static string GetRowValue(DataRow row, string columnName)
        {
            if (row == null || row.Table.Columns.IndexOf(columnName) < 0)
                return string.Empty;
            object value = row[columnName];
            return value == null || value == DBNull.Value ? string.Empty : Convert.ToString(value);
        }

        private static string SanitizeHtml(string html)
        {
            if (string.IsNullOrEmpty(html)) return string.Empty;

            string value = html;
            value = Regex.Replace(value, @"<%[\s\S]*?%>", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"<script\b[^>]*>[\s\S]*?</script\s*>", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"<style\b[^>]*>[\s\S]*?</style\s*>", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"<(?:iframe|object|embed|applet|base|meta|link)\b[^>]*>[\s\S]*?</(?:iframe|object|embed|applet)\s*>", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"<(?:iframe|object|embed|applet|base|meta|link)\b[^>]*/?>", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"</?(?:html|head|body|form)\b[^>]*>", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"</?asp:[^>]*>", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"\srunat\s*=\s*(?:""[^""]*""|'[^']*'|[^\s>]+)", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"\son\w+\s*=\s*(?:""[^""]*""|'[^']*'|[^\s>]+)", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"javascript\s*:", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"data\s*:\s*text/html", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"expression\s*\(", "blocked(", RegexOptions.IgnoreCase);
            return NormalizeBanLanhDaoShell(value);
        }

        private static string NormalizeBanLanhDaoShell(string html)
        {
            if (string.IsNullOrEmpty(html)) return string.Empty;

            string value = html.Trim();
            value = Regex.Replace(
                value,
                @"(<div\s+class\s*=\s*(?:""ban-lanh-dao-page""|'ban-lanh-dao-page')[^>]*>\s*<div\s+class\s*=\s*(?:""ban-lanh-dao-page-body""|'ban-lanh-dao-page-body')[^>]*>)\s*<div\s+class\s*=\s*(?:""ban-lanh-dao-page""|'ban-lanh-dao-page')[^>]*>\s*<div\s+class\s*=\s*(?:""ban-lanh-dao-page-body""|'ban-lanh-dao-page-body')[^>]*>",
                "$1",
                RegexOptions.IgnoreCase);
            value = Regex.Replace(
                value,
                @"(</div>\s*</div>)\s*(</div>\s*</div>)\s*$",
                "$2",
                RegexOptions.IgnoreCase);
            return value;
        }

        private static string EnsureBanLanhDaoRootAttribute(string html)
        {
            if (string.IsNullOrEmpty(html)) return string.Empty;
            if (html.IndexOf("data-ban-lanh-dao-root", StringComparison.OrdinalIgnoreCase) >= 0)
                return html;

            string value = Regex.Replace(
                html,
                @"(<div\s+class\s*=\s*(?:""ban-lanh-dao-page""|'ban-lanh-dao-page')(?:\s[^>]*)?)(>)",
                "$1 data-ban-lanh-dao-root=\"1\"$2",
                RegexOptions.IgnoreCase);
            return value;
        }

        private static string SanitizeCss(string css)
        {
            if (string.IsNullOrEmpty(css)) return string.Empty;

            string value = Regex.Replace(css, @"</\s*style\s*>", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"@import\b[^;]*;", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"expression\s*\(", "blocked(", RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"javascript\s*:", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"behavior\s*:", "blocked-behavior:", RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"-moz-binding\s*:", "blocked-binding:", RegexOptions.IgnoreCase);
            return value;
        }
    }
}

