function buildScopedCss(source) {
  var scopeScript = path.join(root, 'tools', 'scope-css.js');
  var tmpIn = path.join(outDir, '_style_source.css');
  var tmpOut = path.join(outDir, '_style_scoped.css');
  fs.mkdirSync(outDir, { recursive: true });
  fs.writeFileSync(tmpIn, normalizeCssSource(source), 'utf8');
  execFileSync(process.execPath, [scopeScript, tmpIn, tmpOut, '.ban-lanh-dao-page'], {
    cwd: root,
    stdio: 'pipe'
  });
  return fs.readFileSync(tmpOut, 'utf8').replace(/^\/\* Generated from[^\n]*\n/, '');
}

function buildCssBundle(source, includeFontImport) {
  var scoped = buildScopedCss(source);
  var banner = '/* Ban Lanh Dao page styles. Scoped under .ban-lanh-dao-page. */\n\n';
  if (includeFontImport) {
    return '@import url("https://fonts.googleapis.com/css2?family=Lexend:wght@300;400;500;600;700&family=Be+Vietnam+Pro:wght@300;400;500;600;700&display=swap");\n' +
      banner + scoped;
  }
  return banner + scoped;
}

